/* ============================================================
   DATA-VERBOS.JS — Conjugaciones de los verbos del léxico AZBUKA
   ------------------------------------------------------------
   Total: 1656 verbos (todos los posNormalized:"verbo" de
   data-lexicon.js). Generado el 23/09/2026.
   Actualizado el 23/09/2026: 6 verbos nuevos (CMR-05419–05421 y los
   homógrafos separados CMR-05466–05468), 2 entradas huérfanas quitadas
   (CMR-05033 y CMR-05376, duplicados eliminados del léxico) y el acento
   del infinitivo corregido según Zalizniak en подде́рживать, ука́зывать,
   почита́ть (×2), передава́ться y выре́зывать (este también en sus formas).
   Actualizado el 24/09/2026: реализова́ть y минова́ть (biaspectuales)
   pasan a guardar sus formas en "presente", como el resto de los
   biaspectuales; вида́ть suma su presente (вида́ю…), que Zalizniak
   registra como coloquial.
   Actualizado el 24/09/2026 (módulo Diálogos): дое́хать (CMR-05472) y
   потеря́ться (CMR-05473). Formas de OpenRussian, cruzadas con pymorphy3.

   QUÉ HAY ACÁ Y QUÉ NO
   Este archivo guarda SOLO las formas conjugadas. Todo lo demás
   (traducción, definición, aspecto, pareja aspectual, rección,
   transliteración, IPA) se lee de data-lexicon.js por el mismo ID.
   Nunca duplicar acá datos que ya estén en el léxico central.

   Cargar DESPUÉS de data-lexicon.js:
     <script src="data-lexicon.js"></script>
     <script src="data-verbos.js"></script>

   FORMATO DE CADA VERBO (clave = ID del léxico, "CMR-xxxxx")
     ru          infinitivo con acento. Es un ancla de control: sin el
                 acento tiene que ser idéntico a LEXICON_COMER[id].ru.
     presente    imperfectivos y biaspectuales: 6 formas en orden fijo
                 я · ты · он/она/оно · мы · вы · они
     futuro      perfectivos: 6 formas en el mismo orden (el perfectivo
                 no tiene presente). Excepción: быть guarda su futuro
                 explícito (буду…), porque no se puede armar con буду.
     pasado      por género/número, no por persona:
                 m (masc. sing.) · f (fem. sing.) · n (neutro sing.) · pl
     imperativo  ty (tú/vos) · vy (ustedes / usted), o null si no se usa
     nota        (opcional) aclaración de uso en español rioplatense

   null en una posición = esa forma no existe o no se usa (verbos
   impersonales, pasivos, defectivos). La página la muestra como "—".

   REGLAS QUE ARMA LA PÁGINA (no se guardan porque no tienen excepciones)
     · Futuro de los imperfectivos: forma de быть + infinitivo
       (буду говорить). Se arma solo para las personas que tienen
       forma de presente (así un impersonal da solo «будет хотеться»).
     · Condicional: pasado + бы (говорил бы).

   ACENTO: marcado con U+0301 (acento agudo combinable) sobre la vocal
   tónica. No se marca en palabras de una sola vocal ni cuando la
   palabra lleva ё (ё siempre es tónica). Para la voz (TTS) la página
   puede enviar la forma tal cual o sin el acento.

   GUÍA DE RECCIÓN
   Ya no vive acá: se movió a data-gramatica.js (GRAMATICA_RECCION y
   gramaticaReccion), junto con las explicaciones de los casos, para
   que Verbos, Casos y las unidades lean la misma fuente.

   FUENTES Y LICENCIA
   Formas tomadas de los datos de OpenRussian.org (Badestrand/
   russian-dictionary, CC BY-SA 4.0) y contrastadas una por una con el
   analizador morfológico pymorphy3 (diccionario OpenCorpora, CC BY-SA).
   1.538 verbos coincidieron en las dos fuentes; el resto se revisó y
   corrigió a mano (ver INFORME_DATA_VERBOS.md). Por derivar de datos
   CC BY-SA, las tablas de conjugación de este archivo se distribuyen
   bajo CC BY-SA 4.0 (ver LICENSE-CONTENT). Las notas y la guía de
   rección (ahora en data-gramatica.js) son redacción propia de AZBUKA.
   ============================================================ */

